-- Correction: #103 - bug is in get_by_name and search, not get
UPDATE review_findings SET description = 'skill.get_by_name() and search() have reference_list (jsonb) without ::text cast; get() has the cast', evidence = 'skill.gleam: lines 184,214 missing ::text on reference_list; lines 137,144 have it' WHERE review_id = 'ca9e914c-cce6-4db4-b3b1-29779d8e1837' AND finding_number = 103;

-- Correction: #139 - priority is text not int, no status column
UPDATE review_findings SET description = 'broadcast.stats() has 3 bugs: (1) priority is text (low/normal/high/critical) but query does priority >= 2 which is text>=int comparison — always fails; (2) WHERE status = sent but project_communications has no status column; (3) COUNT(*) returns bigint without ::INT cast', evidence = 'broadcast.gleam stats(): priority text>=2, status column does not exist in project_communications, COUNT(*) without ::INT', severity = 'critical' WHERE review_id = 'ca9e914c-cce6-4db4-b3b1-29779d8e1837' AND finding_number = 139;

-- Correction: #155 - exec_sync has shell_escape, reduce severity
UPDATE review_findings SET severity = 'medium', description = 'exec_sync runs shell commands; shell_escape() provides basic sanitization but may not cover all edge cases (newlines, semicolons, pipe characters)', evidence = 'pi_extension_ffi.mjs: exec_sync(cmd); tool_commit.gleam: shell_escape() covers backslash, quote, backtick, dollar sign' WHERE review_id = 'ca9e914c-cce6-4db4-b3b1-29779d8e1837' AND finding_number = 155;

